	/****\
	*    *
	\****/

	IPCNode.reference=function(obj) {
		if (typeof(obj)!=="object" && typeof(obj)!=="function") {
			return obj;
		}
		var owner=obj.__ipc_owner,
			remoteObject;
		if (typeof(owner)!=="object") {
