    def _writeDataReceivePointXML(self, ws, dataReceivePoint):
        lines = []
        lines.append('<%s>'%dataReceivePoint.tag(self.version))
        lines.append(self.indent('<SHORT-NAME>%s</SHORT-NAME>'%dataReceivePoint.name,1))
