  void resetChangesAfterLastFlush() {
    changesAfterLastFlush.set(0);
  }

  void recordLastFlushTime() {
    lastFlushTime = EnvironmentEdgeManager.currentTime();
  }

  @Override
  public void close() {
    closed = true;
    flushThread.interrupt();
    compactExecutor.shutdown();
