    concurrency: argv.concurrency || 1,
    port: argv.port || 5862,
    verbose: argv.verbose,
    node: argv.node,
    inject: argv.inject,
    singleRun: argv['single-run'],
    fastFail: argv['fast-fail'],
    debug: argv.debug,
    svelte: argv.svelte,
    timeout: argv.timeout || 5
};

// Force verbose mode from a CI environment
