        switch (type) {
        case BOOLEAN: return "|b1";
        case CHAR:    return "<S1";
        case INT8:    return "<i1";
        case INT16:   return "<i2";
        case INT32:   return "<i4";
        case INT64:   return "<i8";
        case FLOAT32: return "<f4";
        case FLOAT64: return "<f8";
