                        if (bVersions.isFocusOwner())
                            bTokens.requestFocusInWindow();
                        else if (bTokens.isFocusOwner())
                            bVersions.requestFocusInWindow();
                        e.consume();
                    } else if (e.getKeyCode() == KeyEvent.VK_TAB) {
                        if (bVersions.isFocusOwner() || bTokens.isFocusOwner()) {
