      qb.whereIn('id', parameters.itemId);
    }

    var filterWhere = utils.parseFilters(parameters);
    if (Object.keys(filterWhere).length > 0) {
      qb.where(filterWhere);
    }

    var orderByObj = utils.parseSorting(parameters);
    if (orderByObj) {
