                ModelUpdateUtil.handlePrecedentUpdate(book.getBookSeries(), new RefImpl(book.getBookName(), _sheet.getSheetName(), row1, col1, row2, col2), includePrecedent);
            }
        }
    }

    @Override
    public int getLastIndex() {
        return _lastIndex;
    }

    @Override
    void setIndex(int index) {
        this._index = index;
    }

    @Override
    void setLastIndex(int lastIndex) {
        this._lastIndex = lastIndex;
    }

