            }

            // If we get here we have been closed so throw as such
            throw new IOException("Instance is closed");
        }
    }

    /**
     * {@inheritDoc}
     */
    @Override
    public void close()
    {
        if (myMinion != null) {
            myMinion.close();
            myMinion = null;
        }
    }

    /**
     * {@inheritDoc}
     */
    @Override
    public boolean isClosed()
    {
        return myMinion == null;
    }

    /**
     * {@inheritDoc}
     */
    @Override
    public String toString()
    {
        return "PythonMinion";
    }

