        } else {
            int response = instance.getCore().getRestAPI().toggle(args[1]);

            if (response == 403) {
                instance.sendMessage(sender, localization.get(locale, "err.upgrade-plan"));
                return;
            }

            if (response == 429) {
                instance.sendMessage(sender, localization.get(locale, "err.rate-limit"));
