                return;
            }

            instance.sendMessage(sender, (action.equalsIgnoreCase("add") ? "Added '" : "Removed '") + ip + "' to firewall (" + mode + ")");
        } else {
            instance.sendMessage(sender, localization.get(locale, "usage.firewall"));
        }
    }

