function monotonic(l){
    if(l.length <= 1){
        return true;
    }
    if(l[0] < l[1]){
        for(var i = 1; i < l.length - 1; i++){
            if(l[i] > l[i + 1]){
                return false;
            }
        }
    }
    else{
        for(var i = 1; i < l.length - 1; i++){
            if(l[i] < l[i + 1]){
                return false;
            }
        }
    }
    return true;

