    public void actionPerformed(ActionEvent e) {
        var obj = e.getSource();
        if (obj.equals(btnCancel)) {
            dispose();
        } else if (obj.equals(btnClear)) {
            clearInputData();
        } else if (obj.equals(btnSearchStudent)) {
            searchStudent();
        } else if (obj.equals(btnSearchSubject)) {
            searchSubject();
        } else if (obj.equals(btnRegister)) {
