    depGraph.set(
        "pkgManager",
        mapper.createObjectNode().put("name", toSnykPackageManager(req.pkgManager())));

    depGraph.set("pkgs", addPackages(depGraph, req.tree()));
    ObjectNode root = mapper.createObjectNode().set("depGraph", depGraph);
